/** Bytes the resumed product session left behind, and where. */
function transcriptFootprint(sessionId) {
  if (sessionId === undefined) return { bytes: 0, path: undefined }
  const root = SCOPE_CONFIG ? `${CONFIG_DIR}/projects` : PROJECT_DIR
  if (!existsSync(root)) return { bytes: 0, path: root }
  const listed = execSync(`find ${root} -name '${sessionId}*' -type f -printf '%s %p\\n'`, { encoding: 'utf8' })
